import org.apache.commons.io.input.UnsynchronizedBufferedReader;
import java.io.StringReader;
public class T {
    public static void main(String[] args) throws Exception {
        UnsynchronizedBufferedReader br = new UnsynchronizedBufferedReader(new StringReader("abcdef"));
        char[] buf = new char[4];
        int n1 = br.read(buf, 0, 4);
        System.out.println("n1=" + n1 + " " + new String(buf,0,n1));
        int n2 = br.read(buf, 0, 4);
        System.out.println("n2=" + n2);
        if (n2 > 0) System.out.println(new String(buf,0,n2));
    }
}
